            literals.add(i + 1)
            literals.add(-(i + 1))

        new_var = -1
        for clause in clauses:
            new_var -= 1
            tree[new_var] = []
            for lit in clause:
                if lit > 0:
                    tree[lit].append((new_var, 'not'))
                else:
                    tree[-lit].append((new_var, 'not'))

        return tree, literals

    def rank_of_tree(tree):
        visited = set()
        rank = 0

        def dfs(node):
            nonlocal rank
            if node in visited:
                return
            visited.add(node)
            for neighbor, _ in tree[node]:
                dfs(neighbor)
            rank += 1

        for node in tree:
            if node not in visited:
                dfs(node)

        return rank

    def depth_of_tree(tree):
        def dfs(node, current_depth):
            nonlocal max_depth
            if node in visited:
                return
            visited.add(node)
            max_depth = max(max_depth, current_depth)
            for neighbor, _ in tree[node]:
                dfs(neighbor, current_depth + 1)

        visited = set()
        max_depth = 0
        for node in tree:
            if node not in visited:
                dfs(node, 1)

        return max_depth

    n = random.randint(5, 40)
